const html = `<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="UTF-8">
<title>Wahlkampf-Bildgenerator (Entwurf)</title>
<style>
  body { font-family: Arial, sans-serif; max-width: 640px; margin: 40px auto; padding: 0 16px; background: #f4f4f4; color: #222; }
  h1 { color: #b7202a; }
  form { background: #fff; padding: 24px; border-radius: 8px; box-shadow: 0 1px 4px rgba(0,0,0,0.15); }
  label { display: block; margin-top: 16px; font-weight: bold; }
  textarea, select { width: 100%; padding: 8px; margin-top: 4px; box-sizing: border-box; font-size: 14px; }
  textarea { min-height: 80px; }
  button { margin-top: 24px; background: #b7202a; color: #fff; border: none; padding: 12px 24px; font-size: 16px; border-radius: 4px; cursor: pointer; }
  button:hover { background: #8f1a20; }
  .hinweis { font-size: 13px; color: #555; margin-top: 8px; }
</style>
</head>
<body>
<h1>Wahlkampf-Bildgenerator (Entwurf)</h1>
<p class="hinweis">Erzeugt ein satirisches Sharepic zu einem frei gewaehlten Thema ueber die bestehende Fakten-/Satire-/Bild-Agenten-Kette. Das Ergebnis wird ausschliesslich in Matrix gepostet - es gibt KEINE automatische Veroeffentlichung auf WordPress, Mastodon oder Instagram, und es werden KEINE echten ALLRIS-Vorgaenge beruehrt. Das Bild ist deutlich als "ENTWURF" gekennzeichnet.</p>
<form method="POST" action="/webhook/wahlkampf-bild">
  <label for="thema">Thema *</label>
  <textarea id="thema" name="thema" required placeholder="z.B. Sanierung des Marktplatzes verzoegert sich erneut"></textarea>

  <label for="zusatzkontext">Zusatzkontext (optional)</label>
  <textarea id="zusatzkontext" name="zusatzkontext" placeholder="Zusaetzliche Details, die der generierte Text beruecksichtigen soll"></textarea>

  <label for="sprengstoff">Sprengstoff (Satire-Intensitaet)</label>
  <select id="sprengstoff" name="sprengstoff">
    <option value="GERING">GERING</option>
    <option value="MITTEL" selected>MITTEL</option>
    <option value="HOCH">HOCH</option>
  </select>

  <button type="submit">Bild generieren</button>
</form>
</body>
</html>`;

return [{ json: { html } }];

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const body = $input.first().json.body || {};
const thema = safeStr(body.thema);
if (!thema) throw new Error('Thema fehlt - Formular ohne Thema abgeschickt.');

const zusatzkontext = safeStr(body.zusatzkontext);
const sprengstoffRaw = safeStr(body.sprengstoff).toUpperCase();
const sprengstoff = ['GERING', 'MITTEL', 'HOCH'].includes(sprengstoffRaw) ? sprengstoffRaw : 'MITTEL';

const ts = Date.now();
const vorgangKey = 'wk-' + ts;
const vorgangsnummer = 'ENTWURF';

return [{
  json: {
    thema,
    zusatzkontext,
    sprengstoff,
    vorgangKey,
    vorgangsnummer
  }
}];

