function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

function getAiText(j) {
  if (typeof j.content === 'string') return j.content;
  if (typeof j.text === 'string') return j.text;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) return safeStr(j.choices[0].message.content);
  if (Array.isArray(j.output)) {
    const msg = j.output.find(function(o) { return o && o.type === 'message' && Array.isArray(o.content); });
    const part = msg && msg.content.find(function(c) { return c && typeof c.text === 'string'; });
    if (part) return part.text;
  }
  return safeStr(JSON.stringify(j));
}

const base = $('Normalisiere Eingabe').first().json;
const aiJson = $input.first().json;
const summaryText = safeStr(getAiText(aiJson));
if (!summaryText) throw new Error('Sachverhalt-Generierung lieferte keinen Text.');

return [{
  json: {
    ...base,
    title: base.thema,
    summaryText,
    combinedText: base.thema + '\n\n' + summaryText
  }
}];

const before = $('Parse Sachverhalt').first().json;
const after = $input.first().json;

return [{
  json: {
    ...before,
    sourceTopic: after.sourceTopic,
    sourceConflict: after.sourceConflict,
    requiredTerms: after.requiredTerms,
    requiredObjects: after.requiredObjects,
    requiredAction: after.requiredAction,
    affectedGroups: after.affectedGroups,
    concreteNumbers: after.concreteNumbers,
    responsibilities: after.responsibilities,
    documentType: after.documentType,
    quotesVerbatim: after.quotesVerbatim,
    faktenParseError: after.parseError
  }
}];

const before = $('Stelle Kontext wieder her (Fakten)').first().json;
const after = $input.first().json;

return [{
  json: {
    ...before,
    variants: after.variants,
    kernbotschaft: after.kernbotschaft,
    satireParseError: after.parseError
  }
}];

const j = $input.first().json;
const variants = Array.isArray(j.variants) ? j.variants : [];
if (variants.length === 0) throw new Error('Satire-Agent lieferte keine Varianten (variants leer).');

// Automatische Wahl: mittlere Intensitaet (sortiert nach satireIntensity, Median-Index).
const sorted = variants.slice().sort((a, b) => (Number(a.satireIntensity) || 0) - (Number(b.satireIntensity) || 0));
const chosen = sorted[Math.floor((sorted.length - 1) / 2)];

return [{
  json: {
    ...j,
    satireBrief: chosen.satireBrief,
    satireAngle: chosen.satireAngle,
    satirePunchlines: chosen.satirePunchlines,
    satireTarget: chosen.satireTarget,
    satireIntensity: chosen.satireIntensity,
    satireDoNotClaim: chosen.satireDoNotClaim,
    satireSafetyNote: chosen.satireSafetyNote,
    imageHeadline: chosen.imageHeadline,
    imageSubline: chosen.imageSubline
  }
}];

const before = $('Waehle Variante').first().json;
const after = $input.first().json;

return [{
  json: {
    ...before,
    visualMetaphor: after.visualMetaphor,
    visualPflichtobjekte: after.visualPflichtobjekte,
    visualPflichthandlung: after.visualPflichthandlung,
    visualUeberzeichnung: after.visualUeberzeichnung,
    visualErkennungssatz: after.visualErkennungssatz,
    imagePrompt: after.imagePrompt,
    imageNegativePrompt: after.imageNegativePrompt,
    altText: after.altText,
    bildParseError: after.parseError
  }
}];

const j = $input.first().json;
function safeStr(v) { return (v === null || v === undefined) ? '' : String(v).trim(); }
function short(v, max = 900) {
  const s = safeStr(v);
  return s.length > max ? s.substring(0, max) + '…' : s;
}

const vorgangKey = safeStr(j.vorgangKey);
const safeKey = vorgangKey.replace(/[^a-zA-Z0-9_-]/g, '_');
const basePrompt = safeStr(j.imagePrompt);
const negativeExtra = safeStr(j.imageNegativePrompt);
const imageHeadline = safeStr(j.imageHeadline);
const imageSubline = safeStr(j.imageSubline);
if (!basePrompt) throw new Error('imagePrompt fehlt.');
if (!imageHeadline) throw new Error('imageHeadline fehlt.');
if (!imageSubline) throw new Error('imageSubline fehlt.');

const attempt = Math.max(1, Number(j.imageQaAttempt || 1));
const maxAttempts = Math.max(1, Number(j.imageQaMaxAttempts || 3));
const retryFeedback = safeStr(j.imageQaFeedback);

const mustShow = Array.isArray(j.visualPflichtobjekte) ? j.visualPflichtobjekte : [];
const topicPlain = safeStr(j.sourceTopic || j.thema);
const conflictPlain = safeStr(j.sourceConflict || j.visualUeberzeichnung);
const visibleAction = safeStr(j.requiredAction || j.visualPflichthandlung);
const satiricalExaggeration = safeStr(j.visualUeberzeichnung);
const recognitionSentence = safeStr(j.visualErkennungssatz);

const prompt = [
  'Erstelle ein quadratisches Bild (1024x1024 Pixel) als Grundlage fuer ein satirisches Wahlkampf-UEBUNGS-Sharepic der Partei DIE PARTEI, Kreisverband Goslar. Dieses Bild ist ausdruecklich ein ENTWURF/UEBUNGSMATERIAL, keine echte Berichterstattung ueber einen realen Vorgang.',
  '',
  'QUALITAETSZIEL:',
  'Das gewaehlte Thema soll durch reale Gegenstaende und eine sichtbare Situation im Motiv erkennbar sein.',
  'THEMENSPERRE: Zeige ausschliesslich das folgende Thema und den folgenden Konflikt. Keine zusaetzlichen politischen Themen, keine austauschbare Verwaltungssatire und keine neue Zielscheibe.',
  topicPlain ? 'Konkretes Thema: ' + short(topicPlain, 500) : '',
  conflictPlain ? 'Konkreter Konflikt: ' + short(conflictPlain, 600) : '',
  mustShow.length ? 'Zwingend sichtbar: ' + mustShow.slice(0, 6).join(' | ') : '',
  visibleAction ? 'Zwingend sichtbare Handlung: ' + short(visibleAction, 600) : '',
  satiricalExaggeration ? 'Satirische Ueberzeichnung: ' + short(satiricalExaggeration, 600) : '',
  recognitionSentence ? 'Erkennungstest: ' + short(recognitionSentence, 600) : '',
  '',
  'AUFBAU DES BILDES (von oben nach unten):',
  '',
  '1. ROTER TEXTBALKEN (oberes Viertel, ca. 250px hoch):',
  '   - Hintergrundfarbe: kraeftiges Rot (#b7202a)',
  '   - Headline (gross, fett, weiss, zentriert):',
  '   ' + imageHeadline,
  '   - Subline (mittelgross, weiss, zentriert, direkt darunter):',
  '   ' + imageSubline,
  '   - Ausschliesslich diese zwei Textzeilen; keine Zusatzbeschriftung.',
  '   - Text exakt wie vorgegeben, korrekte deutsche Rechtschreibung.',
  '',
  '2. BITTERBOESES SATIRISCHES MOTIV (untere drei Viertel, ca. 750px hoch):',
  '   - Inhalt: ' + basePrompt,
  '   - Groteske kommunalpolitische Satire-Illustration im halb-realistischen Karikaturstil.',
  '   - Das Thema muss sofort erkennbar sein; die sichtbare Ueberzeichnung muss eindeutig satirisch wirken.',
  '   - Grosse ausdrucksstarke Augen und klare Koerpersprache, soweit passend.',
  '   - Goslar-/Harz-/Altstadt-Anmutung nur wenn thematisch passend.',
  '   - Keine echten Personen, keine Logos, keine Wappen.',
  '',
  'ABSOLUT VERBOTEN IM MOTIVBEREICH:',
  '   - KEIN Text, KEINE Schrift, KEINE Buchstaben, KEINE Zahlen.',
  '   - Headline und Subline nicht im Motiv wiederholen.',
  '   - Keine Beschriftungen auf Plakaten, Schildern oder Bannern.',
  '   - Kein QR-Code, keine echten Personen oder Politikergesichter.'
].filter(Boolean);

if (attempt > 1) {
  prompt.push('');
  prompt.push('VERBINDLICHER NEUVERSUCH ' + attempt + ' VON ' + maxAttempts + ':');
  prompt.push('Der vorherige Versuch hat den roten Textbalken mit Headline/Subline nicht ausreichend sichtbar oder lesbar dargestellt. ' + (retryFeedback || 'Stelle sicher, dass der rote Textbalken oben eindeutig sichtbar ist und Headline sowie Subline vollstaendig und lesbar zeigt.'));
}

if (negativeExtra) {
  prompt.push('');
  prompt.push('Zusaetzlich vermeiden: ' + negativeExtra);
}

return [{
  json: {
    ...j,
    imageHeadline,
    imageSubline,
    motifPrompt: prompt.join('\n'),
    filenameRaw: 'raw_' + safeKey + '.png',
    filenameFinal: 'final_' + safeKey + '.png',
    imageQaAttempt: attempt,
    imageQaMaxAttempts: maxAttempts
  }
}];

const item = $input.item;
const j = item.json || {};
const bin = item.binary || {};
const binKey = Object.keys(bin).find(k => bin[k] && bin[k].mimeType);
if (!binKey) {
  const errMsg = j.error
    ? 'OpenAI Fehler: ' + (j.error.message || JSON.stringify(j.error)).substring(0, 300)
    : 'Kein Bild erhalten: ' + JSON.stringify(j).substring(0, 500);
  throw new Error(errMsg);
}
const ctx = $('Bereite MotivPrompt vor').first().json || {};
const srcBin = { ...bin[binKey] };
srcBin.fileName = ctx.filenameRaw || 'raw_image.png';
srcBin.fileExtension = 'png';
srcBin.mimeType = srcBin.mimeType || 'image/png';
return [{ json: { ...ctx }, binary: { rawImage: srcBin } }];

const rawItem = $input.item;
const bin = rawItem.binary || {};
const ctx = rawItem.json || {};

if (!bin.rawImage)     throw new Error('rawImage fehlt. Keys: '    + Object.keys(bin).join(', '));
if (!bin.overlayImage) throw new Error('overlayImage fehlt. Keys: ' + Object.keys(bin).join(', '));

return [{
  json: { ...ctx },
  binary: {
    rawImage:     bin.overlayImage,
    overlayImage: bin.rawImage
  }
}];

const item = $input.first();
const bin = item.binary || {};
const ctx = item.json || {};

if (!bin.rawImage) throw new Error('rawImage fehlt nach Composite. Keys: ' + Object.keys(bin).join(', '));

const vorgangKey = String(ctx.vorgangKey || '').trim();
if (!vorgangKey) throw new Error('vorgangKey fehlt.');

const finalBin = { ...bin.rawImage };
finalBin.fileName = ctx.filenameFinal || ('final_' + vorgangKey.replace(/[^a-zA-Z0-9_-]/g, '_') + '.png');
finalBin.fileExtension = 'png';
finalBin.mimeType = finalBin.mimeType || 'image/png';

return [{
  json: {
    ...ctx,
    filenameFinal: finalBin.fileName
  },
  binary: { finalImage: finalBin }
}];

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

function getAiText(j) {
  if (typeof j.content === 'string') return j.content;
  if (typeof j.text === 'string') return j.text;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) return safeStr(j.choices[0].message.content);
  if (Array.isArray(j.output)) {
    const msg = j.output.find(function(o) { return o && o.type === 'message' && Array.isArray(o.content); });
    const part = msg && msg.content.find(function(c) { return c && typeof c.text === 'string'; });
    if (part) return part.text;
  }
  return safeStr(JSON.stringify(j));
}

function extractJson(text) {
  const t = safeStr(text).replace(/```json/gi, '```').replace(/```/g, '');
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return null;
  try { return JSON.parse(t.substring(start, end + 1)); } catch (e) { return null; }
}

const finalImageItem = $('Pruefe finalImage').first();
const ctx = finalImageItem.json || {};
const binary = finalImageItem.binary || {};

const aiText = getAiText($input.first().json);
const parsed = extractJson(aiText);

const attempt = Math.max(1, Number(ctx.imageQaAttempt || 1));
const maxAttempts = Math.max(1, Number(ctx.imageQaMaxAttempts || 3));

const headlineVisible = parsed ? parsed.headlineVisible === true : false;
const sublineVisible = parsed ? parsed.sublineVisible === true : false;
const textOk = headlineVisible && sublineVisible;
const canRetry = !textOk && attempt < maxAttempts;

return [{
  json: {
    ...ctx,
    textBannerOk: textOk,
    textBannerCanRetry: canRetry,
    textBannerReason: parsed ? safeStr(parsed.reason) : 'Pruefantwort nicht lesbar',
    imageQaAttempt: attempt,
    imageQaMaxAttempts: maxAttempts,
    imageQaFeedback: 'Roter Textbalken mit Headline "' + safeStr(ctx.imageHeadline) + '" und Subline "' + safeStr(ctx.imageSubline) + '" war beim letzten Versuch nicht vollstaendig sichtbar oder lesbar.'
  },
  binary
}];

const j = $input.first().json;
return [{
  json: {
    ...j,
    imageQaAttempt: Math.max(2, Number(j.imageQaAttempt || 1) + 1)
  }
}];

const item   = $input.item;
const j      = item.json || {};
const binary = item.binary || {};

if (!binary.finalImage) {
  throw new Error('[Matrix] finalImage fehlt fuer Matrix-Post.');
}

const vorgangKey = String(j.vorgangKey || '').trim();
if (!vorgangKey) {
  throw new Error('[Matrix] vorgangKey fehlt.');
}

const filenameFinal = j.filenameFinal || ('final_' + vorgangKey.replace(/[^a-zA-Z0-9_-]/g, '_') + '.png');

const textWarning = (j.textBannerOk === false)
  ? '\n\nACHTUNG: Headline/Subline waren bei der automatischen Pruefung nicht sicher lesbar - bitte Bild manuell kontrollieren.'
  : '';

return {
  json: {
    ...j,
    matrixFilename: filenameFinal,
    matrixTxnId: ('wahlkampf_' + vorgangKey.replace(/[^a-zA-Z0-9_-]/g, '_')).substring(0, 120),
    matrixCaption: 'Wahlkampf-Entwurf (nicht veroeffentlicht) - Thema: ' + String(j.thema || '').substring(0, 200) + textWarning
  },
  binary
};

const upload = $input.item.json || {};
const ctxItem = $('Bereite Matrix Post vor').item;
const ctx = ctxItem.json || {};

const contentUri = upload.content_uri || upload.contentUri;
if (!contentUri) {
  throw new Error('[Matrix] Media Upload hat keine content_uri geliefert: ' + JSON.stringify(upload).substring(0, 500));
}

return {
  json: {
    ...ctx,
    matrixContentUri: contentUri
  },
  binary: ctxItem.binary || {}
};

const html = `<!DOCTYPE html>
<html lang="de"><head><meta charset="UTF-8"><title>Bild erstellt</title>
<style>body{font-family:Arial,sans-serif;max-width:640px;margin:60px auto;padding:0 16px;text-align:center;}
h1{color:#2e7d32;} a{color:#b7202a;}</style></head>
<body><h1>Fertig</h1><p>Das Entwurfs-Sharepic wurde erstellt und in Matrix gepostet.</p>
<p><a href="/webhook/wahlkampf-bild">Neues Thema eingeben</a></p></body></html>`;
return [{ json: { html } }];
